sap.ui.define([
  "sap/m/MessageToast"
], function (MessageToast) {
  "use strict";
  return {
    // list report controller extension, press handler of a custom action
    onRemind: function () {
      const contexts = this.extensionAPI.getSelectedContexts();
      const send = function () {
        return this.extensionAPI.invokeActions("/SendReminder", contexts);
      }.bind(this);
      this.extensionAPI.securedExecution(send).then(function () {
        MessageToast.show("Reminders sent");
      });
    }
  };
});
